package com.ganesh.erp;
import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/students") @CrossOrigin(origins="*") public class StudentController { private final StudentRepository repo; public StudentController(StudentRepository r){repo=r;} @GetMapping public List<Student> all(){return repo.findAll();} @GetMapping("/{id}") public Student one(@PathVariable Long id){return repo.findById(id).orElseThrow();} @PostMapping public Student create(@RequestBody Student s){return repo.save(s);} @PutMapping("/{id}") public Student update(@PathVariable Long id,@RequestBody Student s){Student x=repo.findById(id).orElseThrow();x.name=s.name;x.email=s.email;x.department=s.department;x.year=s.year;x.attendance=s.attendance;return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }
